package org.json;
import com.google.gson.*;
/** Test adapter only: JSON parsing is Gson, never installed into APK. */
public class JSONObject{private JsonObject value;public JSONObject(){value=new JsonObject();}public JSONObject(String s){value=JsonParser.parseString(s).getAsJsonObject();}private JSONObject(JsonObject v){value=v;}public JSONObject put(String k,Object v){if(v instanceof JSONObject)value.add(k,((JSONObject)v).value);else value.add(k,new Gson().toJsonTree(v));return this;}public String getString(String k){return value.get(k).getAsString();}public long getLong(String k){return value.get(k).getAsLong();}public JSONObject getJSONObject(String k){return new JSONObject(value.getAsJsonObject(k));}public static String quote(String s){return new Gson().toJson(s);}public boolean optBoolean(String k){return optBoolean(k,false);}public boolean optBoolean(String k,boolean d){try{return value.get(k).getAsBoolean();}catch(Exception e){return d;}}public boolean isNull(String k){return !value.has(k)||value.get(k).isJsonNull();}public Object opt(String k){return isNull(k)?null:value.get(k);}public boolean has(String k){return value.has(k);}@Override public String toString(){return value.toString();}}
